const MEMBERS=['Jirapat','Mia','Alex'];
const KEY='flat-agree-demo-v3';
const seed=()=>({rules:[{id:'kitchen',title:'Leave the kitchen ready for the next person',category:'Cleaning',description:'Wash your dishes and wipe the counter after cooking. If you are in a rush, let the flat know and finish before the end of the day.',votes:MEMBERS.slice(),comments:[],author:'Mia'},{id:'quiet',title:'A quieter home after 10 pm',category:'Noise',description:'Keep music, calls and shared-space noise low from 10 pm to 8 am. If you are planning something louder, check with everyone first.',votes:MEMBERS.slice(),comments:[],author:'Alex'},{id:'guests',title:'A heads-up for overnight guests',category:'Guests',description:'Let everyone know at least a day before someone stays overnight. For stays longer than two nights, ask the flat first. For unexpected situations such as travel delays, tell the flat as soon as you can.',votes:['Mia'],comments:[{by:'Alex',text:'Thanks for including unexpected situations. Can we clarify who should be notified?'}],author:'Mia'},{id:'shared',title:'Keep a small shared shopping list',category:'Shared things',description:'Add shared essentials like dish soap and bin bags to a list when they run low. Check before buying so we do not double up.',votes:['Alex','Mia'],comments:[],author:'Alex'}],activity:[{text:'Mia proposed a heads-up for overnight guests.',time:'Sample activity'},{text:'Everyone agreed on quieter evenings.',time:'Sample activity'}],checks:[],feedback:[]});
let state;try{state=JSON.parse(localStorage.getItem(KEY));if(!state||!Array.isArray(state.rules)||!Array.isArray(state.feedback)||!Array.isArray(state.checks)||!Array.isArray(state.activity))state=seed()}catch{state=seed()}
let member='Jirapat',page='rules',filter='All rules',search='',editing=null,detailId=null;
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const agreed=r=>MEMBERS.every(m=>r.votes.includes(m));const needsReply=r=>!agreed(r)&&!r.votes.includes(member);const icons={'Cleaning':'✧','Noise':'≈','Guests':'♧','Shared things':'◇'};
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',3400)}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('Browser storage is unavailable. Changes will last only for this visit.')}}
function log(text){state.activity.unshift({text,time:new Date().toLocaleString()})}
function hero(kicker,title,desc,action=''){return `<section class="hero"><div><span class="eyebrow">${kicker}</span><h1>${title}</h1><p>${desc}</p></div>${action}</section>`}
function resources(){return '<div class="mobile-only"><a href="prototype.pdf" target="_blank">Lo-fi prototype ↗</a><a href="https://github.com/chaaawin/flat-agree" target="_blank" rel="noopener">GitHub source ↗</a><button class="text-btn" onclick="openReset()">Reset demo</button></div>'}
function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#breadcrumb').textContent=({rules:'House agreements',welcome:'Moving in',activity:'Activity',feedback:'Test & feedback'})[page];$('#nav-count').textContent=state.rules.filter(r=>!agreed(r)).length;const c=$('#content');if(page==='rules'){c.innerHTML=hero('A SHARED HOME, ON THE SAME PAGE','Little agreements.<br>Better living.','Make the unwritten rules a little more written. Together.','<button class="primary" id="propose">＋ &nbsp; Propose a rule <span>↗</span></button>')+`<section class="reply-banner"><div><span class="eyebrow">YOUR NEXT STEP · V3</span><strong>${state.rules.filter(needsReply).length?`${state.rules.filter(needsReply).length} rule(s) need your response`:'You are up to date'}</strong><p>${state.rules.filter(needsReply).length?'Review the wording and choose whether you agree or want changes.':'All open proposals already have your response.'}</p></div><button class="secondary" id="review-pending">Review my pending rules →</button></section><section class="how-steps" aria-label="How Flat Agree works"><span><b>1</b> Propose a clear rule</span><span><b>2</b> Everyone reviews the same wording</span><span><b>3</b> All 3 agree → House agreement</span></section><section class="banner"><div class="sun">☼</div><div><strong>New keys. Same page.</strong><p>A quick welcome guide to help every roommate feel at home.</p></div><button id="welcome-link">Explore moving in &nbsp; →</button></section><section class="stats" aria-label="Agreement summary"><div class="stat"><span class="stat-number">${state.rules.filter(agreed).length.toString().padStart(2,'0')}</span><span class="stat-label">Agreed together</span><span class="stat-icon">✓</span></div><div class="stat"><span class="stat-number">${state.rules.filter(r=>!agreed(r)).length.toString().padStart(2,'0')}</span><span class="stat-label">Open for discussion</span><span class="stat-icon">↗</span></div><div class="stat"><span class="stat-number">03</span><span class="stat-label">Voices that matter</span><span class="stat-icon">♧</span></div></section><section class="controls"><div class="tabs" role="group" aria-label="Filter rules">${['All rules','Agreed','Discussing','Needs my reply'].map(f=>`<button data-filter="${f}" class="${f===filter?'active':''}">${f}</button>`).join('')}</div><input type="search" id="search" class="search" placeholder="Search house rules…" aria-label="Search house rules" value="${esc(search)}"></section><section class="cards" id="cards" aria-label="House rules"></section>`+resources();$('#propose').onclick=()=>openForm();$('#review-pending').onclick=()=>{filter='Needs my reply';render()};$('#welcome-link').onclick=()=>go('welcome');document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});$('#search').oninput=e=>{search=e.target.value;renderCards()};renderCards()}else if(page==='welcome'){const tasks=[['Read the agreed house rules','Check what everyone has already agreed on. Open a rule to see the details.'],['Introduce your own routine','Talk about your sleep, study and cooking habits with your roommates.'],['Ask about anything unclear','Use a rule discussion to ask a question or suggest a change.'],['Make your first proposal','Something missing? Propose a rule so everyone can have a say.']];c.innerHTML=hero('MAKE YOURSELF AT HOME','A softer landing.','You should not have to guess how your new home works.')+`<div class="banner"><div class="sun">⌂</div><div><strong>Welcome to The Sunday Flat</strong><p>Jirapat, Mia and Alex · Demo household</p></div></div><section class="panel"><h2>Your moving-in checklist</h2><p class="muted">${state.checks.length} of 4 complete · Progress for this browser</p>${tasks.map((t,i)=>`<label class="check-row"><input type="checkbox" data-check="${i}" ${state.checks.includes(i)?'checked':''}><div><strong>${t[0]}</strong><p>${t[1]}</p></div></label>`).join('')}<div class="actions"><button class="primary" id="read-rules">Explore house agreements →</button></div></section>`+resources();c.querySelectorAll('[data-check]').forEach(x=>x.onchange=()=>{const n=Number(x.dataset.check);state.checks=x.checked?[...new Set([...state.checks,n])]:state.checks.filter(i=>i!==n);save();render()});$('#read-rules').onclick=()=>{filter='Agreed';go('rules')}}else if(page==='activity'){c.innerHTML=hero('SMALL STEPS, SHARED DECISIONS','The conversation so far.','A simple record of what changed in your home.')+`<section class="panel timeline">${state.activity.map(a=>`<div class="event"><strong>${esc(a.text)}</strong><p>${esc(a.time)}</p></div>`).join('')}</section>`+resources()}else{c.innerHTML=hero('TRY IT. TELL US. MAKE IT BETTER.','Everyday feedback.','A short test to see whether shared agreements feel clear.')+`<div class="note">Classroom prototype: switch the demo role to simulate three roommates. This is not real authentication or a shared live household. Changes stay in this browser. The Week 3 interviews are illustrative examples; no real interview findings are claimed. The V3 improvements are based on design hypotheses from those examples, not observed interview results.</div><div class="feedback-grid"><section class="panel"><h2>Try these three tasks</h2><ol class="tasks"><li>Find an agreed rule about kitchen cleaning.</li><li>Propose a new rule about guests. Switch demo roles and have every roommate agree.</li><li>Suggest a change to that rule. Confirm the warning and notice how earlier agreements are cleared.</li><li>Switch to a roommate who has not agreed and find the rule using “Needs my reply”.</li></ol><p class="muted">Watch where the tester hesitates. Ask what they expected before explaining the screen. Testing notes are linked in the GitHub repository.</p><a class="secondary" href="prototype.pdf" target="_blank">Open the lo-fi design ↗</a></section><section class="panel"><h2>How did it feel?</h2><form id="feedback-form"><label>How easy were the tasks?<select id="rating"><option>Very easy</option><option>Mostly easy</option><option>A little confusing</option><option>Very confusing</option></select></label><label>What was unclear or missing?<textarea id="feedback-text" required maxlength="1500" rows="4" placeholder="What happened, and what did you expect?"></textarea></label><button class="primary">Save feedback locally →</button></form></section></div><section class="panel"><h2>Feedback notes (${state.feedback.length})</h2>${state.feedback.length?state.feedback.map(f=>`<div class="feedback-item"><strong>${esc(f.rating)}</strong><br>${esc(f.text)}<br><small>${esc(f.time)}</small></div>`).join(''):'<p class="muted">No feedback collected yet. Saved notes will appear here.</p>'}<button id="export" class="secondary">Download feedback notes ↓</button></section>`+resources();$('#feedback-form').onsubmit=e=>{e.preventDefault();const text=$('#feedback-text').value.trim();if(!text)return;state.feedback.push({rating:$('#rating').value,text,time:new Date().toLocaleString()});save();render();toast('Feedback saved in this browser.')};$('#export').onclick=()=>{const blob=new Blob([JSON.stringify({project:'Flat Agree',researchStatus:'Interview examples were hypothetical; real participant testing not yet conducted',feedback:state.feedback},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='flat-agree-feedback.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}}}
function renderCards(){const rules=state.rules.filter(r=>(filter==='All rules'||(filter==='Agreed'&&agreed(r))||(filter==='Discussing'&&!agreed(r))||(filter==='Needs my reply'&&needsReply(r)))&&`${r.title} ${r.description} ${r.category}`.toLowerCase().includes(search.toLowerCase()));$('#cards').innerHTML=rules.length?rules.map(r=>`<article class="card"><div class="card-top"><span class="category"><span class="category-icon">${icons[r.category]||'◇'}</span>${esc(r.category)}</span><span class="badge ${agreed(r)?'':'pending'}">${agreed(r)?'✓ Agreed':'◌ Discussing'}</span></div><h2>${esc(r.title)}</h2><p>${esc(r.description)}</p><div class="card-bottom"><span class="votes"><span class="vote-dots">${MEMBERS.map(m=>`<i class="${r.votes.includes(m)?'yes':''}"></i>`).join('')}</span>${r.votes.length}/3 agree <small class="awaiting">${agreed(r)?'• All confirmed':'• Waiting for '+MEMBERS.filter(m=>!r.votes.includes(m)).join(', ')}</small></span><button data-rule="${r.id}">${agreed(r)?'View agreement':'Join discussion'} &nbsp; →</button></div></article>`).join(''):'<div class="empty">No rules here yet. Try another filter or propose a new one.</div>';document.querySelectorAll('[data-rule]').forEach(b=>b.onclick=()=>openDetail(b.dataset.rule))}
function go(p){page=p;render()}
function openForm(id=null){editing=id;const r=state.rules.find(r=>r.id===id);$('#form-title').textContent=r?'Suggest a change':'Propose a house rule';$('#rule-title').value=r?.title||'';$('#rule-description').value=r?.description||'';$('#rule-category').value=r?.category||'Cleaning';$('#edit-note').textContent=r?'Changing a rule clears earlier votes. Every roommate needs to agree to the new version.':'Your proposal starts with your agreement. Your roommates can agree or suggest changes.';$('#rule-dialog').showModal()}
$('#rule-form').onsubmit=e=>{e.preventDefault();const title=$('#rule-title').value.trim(),description=$('#rule-description').value.trim();if(!title||!description){toast('Please add a title and a clear description.');return}if(editing){const r=state.rules.find(r=>r.id===editing);if(!window.confirm('Publishing this change will clear all previous agreements, including yours. All roommates must review the new wording. Continue?'))return;r.history=[...(r.history||[]),{version:r.version||1,by:member,title:r.title,description:r.description}];Object.assign(r,{title,description,category:$('#rule-category').value,votes:[member],version:(r.version||1)+1});r.comments.push({by:member,text:'Suggested a new version. Earlier votes were cleared.'});log(`${member} suggested a new version of “${title}”.`)}else{state.rules.unshift({id:`rule-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,10)}`,title,description,category:$('#rule-category').value,votes:[member],comments:[],author:member});log(`${member} proposed “${title}”.`)}save();$('#rule-dialog').close();filter='All rules';search='';go('rules');toast(editing?'Change shared. Everyone needs to agree again.':'Proposal shared. Your roommates can now respond.')};
function openDetail(id){detailId=id;drawDetail();$('#detail-dialog').showModal()}
function drawDetail(){const r=state.rules.find(r=>r.id===detailId);$('#detail-content').innerHTML=`<div class="dialog-heading"><span class="eyebrow">${esc(r.category)} · PROPOSED BY ${esc(r.author)}</span><button class="close" id="close-detail" aria-label="Close dialog">×</button></div><h2>${esc(r.title)}</h2><p class="version-label">Version ${r.version||1} · Changes require new agreement</p><span class="badge ${agreed(r)?'':'pending'}">${agreed(r)?'✓ Agreed by everyone':'Open for discussion'}</span><p>${esc(r.description)}</p><div class="what-next"><strong>${agreed(r)?'Agreed by everyone':'What happens next?'}</strong><p>${agreed(r)?'All roommates accepted this version. Changes will reopen the discussion.':`${r.votes.length} of 3 people agree. Waiting for ${MEMBERS.filter(m=>!r.votes.includes(m)).join(' and ')} to review this exact wording.`}</p></div><div class="detail-votes">${MEMBERS.map(m=>`<div class="member-vote"><strong>${m}${m===member?' (current demo role)':''}</strong><span>${r.votes.includes(m)?'✓ Agrees':'Awaiting response'}</span></div>`).join('')}</div><div class="actions"><button class="primary" id="vote">${r.votes.includes(member)?'Withdraw my agreement':'I agree with this rule'}</button><button class="secondary" id="edit-rule">Suggest a change</button></div><p class="helper">A rule is agreed only when all three roommates accept the same version.</p>${r.history?.length?`<details class="history"><summary>Previous wording (${r.history.length})</summary>${r.history.slice().reverse().map(h=>`<div class="history-item"><b>Version ${h.version} · ${esc(h.by)}</b><p>${esc(h.title)} — ${esc(h.description)}</p></div>`).join('')}</details>`:''}<h3>Talk it through (${r.comments.length})</h3>${r.comments.map(c=>`<div class="comment"><strong>${esc(c.by)}</strong><p>${esc(c.text)}</p></div>`).join('')}<form id="comment-form"><label>Comment as ${member}<textarea id="comment-text" required maxlength="800" rows="2" placeholder="Ask a question or explain what would work for you."></textarea></label><button class="secondary">Add comment</button></form>`;$('#close-detail').onclick=()=>$('#detail-dialog').close();$('#vote').onclick=()=>{if(r.votes.includes(member)){r.votes=r.votes.filter(m=>m!==member);log(`${member} withdrew agreement on “${r.title}”.`)}else{r.votes.push(member);log(`${member} agreed to “${r.title}”.`)}save();render();drawDetail();toast(agreed(r)?'Everyone agreed. It is now a house agreement.':'Your response was saved.')};$('#edit-rule').onclick=()=>{$('#detail-dialog').close();openForm(r.id)};$('#comment-form').onsubmit=e=>{e.preventDefault();const text=$('#comment-text').value.trim();if(!text)return;r.comments.push({by:member,text});log(`${member} commented on “${r.title}”.`);save();drawDetail();toast('Comment added.')}}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>go(b.dataset.page));$('#member').onchange=e=>{member=e.target.value;$('#profile-avatar').textContent=member[0];render();toast(`Demo role: ${member}. No separate sign-in is simulated.`)};$('.close').onclick=()=>$('#rule-dialog').close();function openReset(){$('#reset-dialog').showModal()}$('#reset').onclick=openReset;$('#cancel-reset').onclick=()=>$('#reset-dialog').close();$('#confirm-reset').onclick=()=>{state=seed();save();$('#reset-dialog').close();filter='All rules';search='';render();toast('Sample household restored.')};save();render();
